// Parse the LLM's structured report JSON, falling back to a plain-numbers summary if needed
const item = $input.item.json;
const raw = item.text || item.output || item.response || '{}';
const calc = $('JS - Calculate Carbon Emissions').item.json;

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    reportTitle: `${calc.facilityName} - Carbon Emissions Report`,
    executiveSummary: `Total emissions for the period were ${calc.totalEmissionsKg} kg CO2e (category: ${calc.emissionCategory}). Electricity contributed ${calc.electricityEmissionsKg} kg CO2e and fuel contributed ${calc.fuelEmissionsKg} kg CO2e.`,
    keyMetrics: [
      `Electricity: ${calc.electricityEmissionsKg} kg CO2e`,
      `Fuel: ${calc.fuelEmissionsKg} kg CO2e`,
      `Total: ${calc.totalEmissionsKg} kg CO2e`
    ],
    recommendations: [],
    trend: '',
    tags: [calc.emissionCategory]
  };
}

return {
  json: {
    ...calc,
    reportTitle: parsed.reportTitle || `${calc.facilityName} - Carbon Emissions Report`,
    executiveSummary: parsed.executiveSummary || '',
    keyMetrics: parsed.keyMetrics || [],
    recommendations: parsed.recommendations || [],
    trend: parsed.trend || '',
    tags: parsed.tags || [],
    generatedAt: new Date().toISOString()
  }
};

